import { useMemo, useState } from 'react'
import { Compass } from 'lucide-react'
import { useCampus, useMovementDaySlot, useMovement } from '../lib/hooks'
import type { MovementTransition, Room, ScheduleEntry } from '../lib/types'
import { cn } from '../lib/utils'
import { Button, Modal } from '../components/ui'
import { UtilizationRing } from '../components/charts'

const SLOT_HOURS = 1.5
const WEEK_SLOTS = 35

interface BuildingStats {
  rooms: number
  labs: number
  seats: number
  sessions: number
  occupied_hours: number
  utilization_pct: number
  conflicts: number
}

export function DigitalCampusPage() {

  const { data: campusStore, isLoading, isError, error, refetch } = useCampus()
  const campusPayload = campusStore ?? undefined
  const campus = campusPayload?.campus
  const schedule: ScheduleEntry[] = campusPayload?.baseline_schedule ?? []
  const [selectedBuilding, setSelectedBuilding] = useState<string | null>(null)
  const [selectedRoom, setSelectedRoom] = useState<string | null>(null)
  const [detail, setDetail] = useState<ScheduleEntry | null>(null)

  const peak = useMemo(() => {
    const days = campusPayload?.days ?? []
    const timeSlots = campusPayload?.time_slots ?? []
    if (!days.length || !timeSlots.length) return { day: 0, slot: 0 }
    let best = { day: 0, slot: 0, busy: -1 }
    for (let dayIndex = 0; dayIndex < days.length; dayIndex += 1) {
      for (let slotIndex = 0; slotIndex < timeSlots.length; slotIndex += 1) {
        const busy = new Set(
          schedule
            .filter((entry) => !entry.displaced && entry.day === dayIndex && (entry.start_slot ?? 0) <= slotIndex && slotIndex < (entry.start_slot ?? 0) + entry.length)
            .map((entry) => entry.room_id),
        ).size
        if (busy > best.busy) best = { day: dayIndex, slot: slotIndex, busy }
      }
    }
    return { day: best.day, slot: best.slot }
  }, [campusPayload, schedule])

  const effectiveDay = campusPayload && peak.day < (campusPayload.days?.length ?? 0)
    ? peak.day
    : 0
  const effectiveSlot = campusPayload && peak.slot < (campusPayload.time_slots?.length ?? 0)
    ? peak.slot
    : 0

  const { data: movementData } = useMovementDaySlot(effectiveDay, effectiveSlot)

  const roomById = useMemo(() => {
    const map = new Map<string, Room>()
    for (const room of campusPayload?.rooms ?? []) map.set(room.id, room)
    return map
  }, [campusPayload])

  const buildingById = useMemo(() => {
    const map = new Map<string, Building>()
    for (const building of campusPayload?.buildings ?? []) map.set(building.id, building)
    return map
  }, [campusPayload])

  const buildingIdForRoom = (roomId: string | null): string | null => {
    if (!roomId) return null
    const room = roomById.get(roomId)
    return room?.building_id ?? null
  }

  const statsByBuilding = useMemo(() => {
    if (!campus) return new Map<string, BuildingStats>()
