      const roomIds = new Set(rooms.map((room) => room.id))
      const entries = schedule.filter((entry) => entry.room_id && roomIds.has(entry.room_id) && !entry.displaced)
      let concurrentConflicts = 0
      const occupancyByRoomSlot = new Map<string, number>()
      for (const entry of entries) {
        if (entry.start_slot === undefined || entry.start_slot === null) continue
        for (let offset = 0; offset < entry.length; offset += 1) {
          const key = `${entry.room_id}:${entry.day}:${entry.start_slot + offset}`
          const next = (occupancyByRoomSlot.get(key) ?? 0) + 1
          occupancyByRoomSlot.set(key, next)
          if (next === 2) concurrentConflicts += 1
        }
      }
      stats.set(building.id, {
        rooms: rooms.length,
        labs: rooms.filter((room) => room.kind === 'lab').length,
        seats: rooms.reduce((sum, room) => sum + room.capacity, 0),
        sessions: entries.length,
        occupied_hours: entries.reduce((sum, entry) => sum + entry.length * SLOT_HOURS, 0),
        utilization_pct: rooms.length
          ? Math.round((entries.reduce((sum, entry) => sum + entry.length, 0) / (rooms.length * WEEK_SLOTS)) * 100)
