    const buildings = campusPayload?.buildings ?? []
    const rooms = campusPayload?.rooms ?? []
    if (!buildings.length || !rooms.length || !schedule.length) return new Map<string, BuildingStats>()

    const stats = new Map<string, BuildingStats>()
    let totalOccupiedHours = 0
    for (const building of buildings) {
      const buildingRooms = rooms.filter((room) => room.building_id === building.id)
      const sessionCount = schedule.filter((entry) => entry.room_id && buildingRooms.some((r) => r.id === entry.room_id) && !entry.displaced).length
      let concurrentConflicts = 0
      for (let i = 0; i < schedule.length; i += 1) {
        const entry = schedule[i]
        if (entry.displaced || !entry.room_id) continue
        if (!buildingRooms.some((r) => r.id === entry.room_id)) continue
        for (let offset = 0; offset < entry.length; offset += 1) {
          for (let j = i + 1; j < schedule.length; j += 1) {
            const other = schedule[j]
            if (other.displaced || !other.room_id) continue
            if (!buildingRooms.some((r) => r.id === other.room_id)) continue
            if (entry.day === other.day && Math.abs(entry.start_slot - other.start_slot) < entry.length + other.length) {
              concurrentConflicts += 1
            }
          }
        }
      }
      stats.set(building.id, {
        rooms: buildingRooms.length,
        labs: buildingRooms.filter((room) => room.kind === 'lab').length,
        seats: buildingRooms.reduce((sum, room) => sum + room.capacity, 0),
        sessions: sessionCount,
        occupied_hours: buildingRooms.reduce((sum, room) => sum + (schedule.filter((e) => e.room_id === room.id && !e.displaced).reduce((s, e) => s + e.length * SLOT_HOURS, 0)), 0),
        utilization_pct: buildingRooms.length
          ? Math.round((sessionCount / (buildingRooms.length * WEEK_SLOTS)) * 100)
          : 0,
        conflicts: concurrentConflicts / 2,
      })
      totalOccupiedHours += sessionCount * SLOT_HOURS
    }

    return stats
  }, [campusPayload, schedule])
